    base = 40 if background else 30
    if isinstance(color, str):
        if color not in _COLORS:
            raise TypeError(f"Unknown color {color!r}.")
        code = _COLORS[color]
        if background:
            code = code + 10
        return str(code)
    if isinstance(color, int) and not isinstance(color, bool):
        if not 0 <= color <= 255:
            raise ValueError("Color number must be in 0-255.")
        return f"{base + 8}" if False else f"{'48' if background else '38'};5;{color}"
    if isinstance(color, (tuple, list)) and len(color) == 3:
        for c in color:
            if not isinstance(c, int) or not 0 <= c <= 255:
                raise ValueError("RGB components must be integers in 0-255.")
        return f"{'48' if background else '38'};2;{color[0]};{color[1]};{color[2]}"
    raise TypeError(f"Invalid color {color!r}.")


