            if ch == "":
                raise EOFError()
            return ch
    old = termios.tcgetattr(fd)
    try:
        tty.setraw(fd)
        ch = os.read(fd, 1).decode("utf-8", "replace")
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
    if ch == "\x03":
        raise KeyboardInterrupt()
    if ch == "\x04":
        raise EOFError()
    if echo:
        echo_text = ch
        sys.stdout.write(echo_text)
        sys.stdout.flush()
    return ch


def pause(info=None, err=False):
    stream = sys.stderr if err else sys.stdout
    if not (_is_tty(sys.stdin) and _is_tty(stream)):
        return
    echo(info if info is not None else "Press any key to continue...", file=stream, nl=False, err=err)
    try:
        getchar()
    except (KeyboardInterrupt, EOFError):
        pass
    echo("", file=stream, err=err)


def edit(text=None, editor=None, env=None, require_save=True, extension=".txt", filename=None):
    editor = editor or os.environ.get("VISUAL") or os.environ.get("EDITOR") or "vi"
    if filename is not None:
        path = os.fspath(filename)
        subprocess.call(shlex.split(editor) + [path], env=env)
        return None
    fd, path = tempfile.mkstemp(suffix=extension)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(text or "")
        before = os.path.getmtime(path)
        subprocess.call(shlex.split(editor) + [path], env=env)
        if require_save and os.path.getmtime(path) == before:
            return None
        with open(path, encoding="utf-8") as f:
            return f.read()
    finally:
        os.unlink(path)


def launch(url, wait=False, locate=False):
    opener = "open" if sys.platform == "darwin" else "xdg-open"
    args = [opener, url]
    if sys.platform.startswith("win"):
        return os.startfile(url) or 0
    try:
        proc = subprocess.Popen(args)
    except OSError:
        return 127
    if wait:
        return proc.wait()
    return 0


def clear():
    if _is_tty(sys.stdout):
        sys.stdout.write("\033[2J\033[H")
        sys.stdout.flush()


def get_app_dir(app_name, roaming=True, force_posix=False):
    if force_posix or sys.platform not in ("darwin", "win32"):
        folder = re.sub(r"\s+", "-", app_name.lower())
        if force_posix:
            return os.path.join(os.path.expanduser("~"), "." + folder)
        xdg = os.environ.get("XDG_CONFIG_HOME")
        base = xdg if xdg else os.path.join(os.path.expanduser("~"), ".config")
        return os.path.join(base, folder)
    if sys.platform == "darwin":
        return os.path.join(os.path.expanduser("~"), "Library", "Application Support", app_name)
    return os.path.join(os.environ.get("APPDATA", os.path.expanduser("~")), app_name)


def format_filename(filename, shorten=False):
    if isinstance(filename, bytes):
        text = os.fsdecode(filename)
    else:
        text = os.fspath(filename)
    text = text.encode("utf-8", "surrogateescape").decode("utf-8", "replace")
    if shorten:
        text = os.path.basename(text)
    return text


def open_file(filename, mode="r", encoding=None, errors="strict", lazy=False, atomic=False):
    if filename == "-":
        if "r" in mode:
            stream = sys.stdin.buffer if "b" in mode else sys.stdin
        else:
            stream = sys.stdout.buffer if "b" in mode else sys.stdout
        return _NonClosing(stream)
    if lazy:
        return LazyFile(filename, mode, encoding, errors, atomic=atomic)
    if "w" in mode and atomic:
        return _AtomicFile(filename, mode, encoding, errors)
    return open(filename, mode, encoding=None if "b" in mode else encoding, errors=errors)


class _NonClosing:
    """Wrap a standard stream so that leaving the block does not close it."""

    def __init__(self, stream):
        self._stream = stream

    def __getattr__(self, name):
        return getattr(self._stream, name)

    def close(self):
        pass

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return False


class _AtomicFile:
    def __init__(self, filename, mode, encoding, errors):
        self._target = filename
        self._dir = os.path.dirname(os.path.abspath(filename))
        fd, self._tmp = tempfile.mkstemp(dir=self._dir, prefix=".optlyn-")
        os.close(fd)
        self._f = open(self._tmp, mode, encoding=None if "b" in mode else encoding, errors=errors)

    def __getattr__(self, name):
        return getattr(self._f, name)

    def write(self, data):
        return self._f.write(data)

    def close(self):
        if self._f.closed:
            return
        self._f.close()
        os.replace(self._tmp, self._target)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False


class LazyFile:
    """Opens on first I/O. A write-mode file is not truncated until it is used."""

    def __init__(self, filename, mode, encoding=None, errors="strict", atomic=False):
        self.name = filename
        self.mode = mode
        self.encoding = encoding
        self.errors = errors
        self.atomic = atomic
        self._f = None

    def _open(self):
        if self._f is None:
            try:
                self._f = open_file(self.name, self.mode, self.encoding, self.errors,
                                    lazy=False, atomic=self.atomic)
            except OSError as exc:
                from .exceptions import OptlynError

                raise OptlynError(f"Could not open file {self.name!r}: {exc.strerror}")
        return self._f

    def __getattr__(self, name):
        return getattr(self._open(), name)

    def write(self, data):
        return self._open().write(data)

    def read(self, *args):
        return self._open().read(*args)

    def close(self):
        if self._f is not None:
            self._f.close()

    def close_intermediate(self):
        self.close()

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False


def _default_prompt_text(name):
    return name.replace("_", " ").capitalize()


def prompt(text, default=None, hide_input=False, confirmation_prompt=False, type=None,
           value_proc=None, prompt_suffix=": ", show_default=True, err=False):
    from .types import STRING, _to_type

    ptype = _to_type(type) if type is not None else (STRING if default is None else _to_type(type_from_default(default)))
    stream = sys.stderr if err else sys.stdout
    while True:
        shown = text
        if default is not None and show_default:
            shown = f"{text} [{default}]"
        echo(shown + prompt_suffix, file=stream, nl=False, err=err)
        line = _read_line(hide_input)
        if line == "" and default is not None:
            value = default() if callable(default) else default
        else:
            if line is None:
                raise Abort()
            value = line
        try:
            value = ptype.convert(value)
        except Exception as exc:
            echo(f"Error: {getattr(exc, 'message', exc)}", file=stream, err=err)
            continue
        if confirmation_prompt:
            echo("Repeat for confirmation" + prompt_suffix, file=stream, nl=False, err=err)
            again = _read_line(hide_input)
            if again != line:
                echo("Error: The two entered values do not match.", file=stream, err=err)
                continue
        return value


def type_from_default(default):
    from .types import infer_type, STRING

    return infer_type(default) or STRING


def _read_line(hide_input):
    if hide_input and _is_tty(sys.stdin):
        import getpass

        try:
            return getpass.getpass(prompt="")
        except EOFError:
            return None
    line = sys.stdin.readline()
    if line == "":
        return None
    return line.rstrip("\r\n")


def confirm(text, default=False, abort=False, prompt_suffix=": ", show_default=True,
            err=False):
    stream = sys.stderr if err else sys.stdout
    if default is True:
        hint = "[Y/n]"
    elif default is False:
        hint = "[y/N]"
    else:
        hint = "[y/n]"
    while True:
        echo(f"{text} {hint}{prompt_suffix}", file=stream, nl=False, err=err)
        line = _read_line(hide_input=False)
        if line is None:
            raise Abort()
        answer = line.strip().lower()
        if answer == "":
            value = default
            break
        if answer in ("y", "yes"):
            value = True
            break
        if answer in ("n", "no"):
            value = False
            break
    if not value and abort:
        raise Abort()
    return value

