        dv = self.default
        if callable(dv):
            dv = dv()
        return dv

    def process_value(self, value, ctx, source, ctx_source=None):
        """Apply the parameter callback. Refusals raise BadParameter."""
        if self.callback is not None:
            value = self.callback(ctx, self, value)
        return value


class Option(Parameter):
    param_type_name = "option"

    def __init__(self, param_decls=None, cls=None, is_flag=None, flag_value=None, count=False,
                 prompt=False, prompt_required=True, hide_input=False,
                 confirmation_prompt=False, allow_from_autoenv=True, **attrs):
        self.is_flag = is_flag
        self.flag_value = flag_value
        self.count = count
        self.prompt = prompt
        self.prompt_required = prompt_required
        self.hide_input = hide_input
        self.confirmation_prompt = confirmation_prompt
        self.allow_from_autoenv = allow_from_autoenv
        self._prompt_text_override = prompt if isinstance(prompt, str) else None
        super().__init__(param_decls, **attrs)
        if self.is_flag is None:
            self.is_flag = (
                isinstance(self.secondary_opts, list) and bool(self.secondary_opts)
            ) or isinstance(self.type, type(BOOL)) and self.default is not None and isinstance(self.default, bool) or False
        if self.count:
            self.is_flag = False
        if self.flag_value is None and self.is_flag:
            self.flag_value = not (self.default is True)
        self._check_declaration()
        self._finish_type()
        if self.is_flag:
            if self.type is None or self.type is STRING:
                self.type = BOOL
            if self.default is None:
                self.default = False
            self.nargs = 0 if self.nargs is None else self.nargs
        if self.count:
            self.nargs = 0
        if self.is_flag and self.prompt is not False:
            raise DeclarationError("A flag option cannot take a prompt.")
        if self.deprecated and self.prompt:
            raise DeclarationError("A deprecated option cannot use a prompt.")
        if self.nargs is None:
            self.nargs = 1

    # -- declaration -------------------------------------------------------

    def _parse_decls(self, decls):
        opts, secondary = [], []
        name = None
        for decl in decls:
            if not decl:
                continue
            if decl[0] in _PREFIX_CHARS + ("/", "+") and not decl.isidentifier():
                if "/" in decl[1:] and decl[0] in _PREFIX_CHARS:
                    first, second = decl.split("/", 1)
                    opts.append(first)
                    secondary.append(second)
                    self._pair = True
                    continue
                opts.append(decl)
            elif decl.isidentifier():
                name = decl
            else:
                opts.append(decl)
        if name is None:
            name = self._infer_name(opts)
        return name, opts, secondary

    def _infer_name(self, opts):
        candidates = [o for o in opts]
        for o in candidates:
            bare = o.lstrip("-/+")
            if bare.isidentifier():
                return bare
        longs = [o for o in candidates if o.startswith("--")]
        shorts = [o for o in candidates if not o.startswith("--")]
        pick = (longs or shorts or ["x"])[0]
        return pick.lstrip("-/+").replace("-", "_")

    def get_error_hint(self):
        return "/".join(self.opts) if self.opts else self.name

    def _default_metavar(self):
        if self.is_flag or self.count:
            return None
        return self.type.get_metavar(self) or self.type.name.upper()

    def get_metavar(self, ctx=None):
        if self.metavar is not None:
            return self.metavar
        return self._default_metavar()

    def all_names(self):
        return list(self.opts) + list(self.secondary_opts)

    # -- value resolution --------------------------------------------------

    def value_from_env(self, ctx):
        """Return the value supplied by the environment, or None (ENV tier)."""
        names = self._env_names(ctx)
        auto = None
        prefix = ctx.auto_envvar_prefix if ctx is not None else None
        if prefix and self.allow_from_autoenv:
            auto = ctx.auto_envvar_name(self)
            if auto:
                names = names + [auto]
        for name in names:
            raw = os.environ.get(name)
            if raw is None or raw == "":
                continue
            if self.is_flag:
                return self._flag_from_env(raw, ctx)
            return self.resolve_envvar_value(ctx, raw)
        return None

    def _flag_from_env(self, raw, ctx):
        text = raw.strip().lower()
        if self.flag_value is not None and not isinstance(self.flag_value, bool):
            if raw == str(self.flag_value):
                return self.flag_value
        if text in _TRUE_ENV:
            return self.flag_value if self.flag_value is True or self.flag_value is None or not isinstance(self.flag_value, bool) else True
        if text in _FALSE_ENV or text == "":
            return False if text != "" else None
        raise UsageError(f"Invalid value for {self.get_error_hint()}: {raw!r} is not a valid flag value.", ctx)

    def default_convert(self, ctx):
        """Convert the declared default or default-map value to the parameter value."""
        return None

    def convert_list(self, values, ctx):
        """Convert repeatable occurrences (already tokenized) into the delivered value."""
        return tuple(self.convert_occurrence(v, ctx) for v in values)


class Argument(Parameter):
    param_type_name = "argument"

    def __init__(self, param_decls=None, cls=None, required=None, nargs=None, **attrs):
        self._required_explicit = required
        super().__init__(param_decls, required=required, nargs=nargs, **attrs)
        self._check_declaration()
        self._finish_type()
        if self.nargs is None:
            self.nargs = 1
        if self.required is None:
            self.required = self.default is None
        self._check_argument_rules()

    def _parse_decls(self, decls):
        if len(decls) != 1:
            raise DeclarationError("An argument takes exactly one destination name.")
        name = decls[0]
        if name.startswith("-"):
            raise DeclarationError("An argument name cannot start with a dash.")
        return name, [], []

    def _check_argument_rules(self):
        if self.deprecated and self.required:
            raise DeclarationError("A deprecated argument cannot be required.")
        if self.deprecated and self.default is None and not self._required_explicit:
            raise DeclarationError("A deprecated argument cannot be left without a default.")

    def _default_metavar(self):
        return self.name.upper()

    def get_error_hint(self):
        return self.get_metavar()

    def is_variadic(self):
        return self.nargs == -1

    def value_from_env(self, ctx):
        raw = self._read_environment(ctx)
        if raw is None:
            return None
        if self.is_variadic() or self.nargs not in (None, 1):
            return self.resolve_envvar_value(ctx, raw)
        return self._convert_one(raw, ctx)

    def convert_list(self, values, ctx):
        if self.is_variadic():
            return tuple(self._convert_one(v, ctx) for v in values)
        if self.nargs == 1:
            return self._convert_one(values[0], ctx)
        return tuple(self._convert_one(v, ctx) for v in values)


def resolve_value_sources(param, ctx, cmdline_value, has_cmdline, prompt_flag_pending):
    """Pick a value by source rank. Returns (value, source) with source None if none applies.

    Ranking (FP-03): prompt, command line, environment, default map, declared default.
    The prompt tier actually runs only when no command-line value exists.
    """
    if has_cmdline:
        return cmdline_value, ParameterSource.COMMANDLINE

    env_value = param.value_from_env(ctx) if hasattr(param, "value_from_env") else None
    if env_value is not None:
        return env_value, ParameterSource.ENVIRONMENT

    dm_value = ctx.default_map_value(param) if ctx is not None else None
    dm_present = dm_value is not None

    if isinstance(param, Option) and param.prompt and (param.prompt_required or prompt_flag_pending):
        default = dm_value if dm_present else (param.default if not dm_present else None)
        if default is None and not dm_present:
            default = param.default
        text = param._prompt_text_override or param.name.replace("_", " ").capitalize()
        value = utils.prompt(
            text,
            default=default,
            hide_input=param.hide_input,
            confirmation_prompt=param.confirmation_prompt,
            type=param.type,
        )
        return value, ParameterSource.PROMPT

    if dm_present:
        return dm_value, ParameterSource.DEFAULT_MAP

    if param.default is not None:
        return param.default_value(ctx), ParameterSource.DEFAULT
    return None, None


def convert_default_map(param, value, ctx):
    """Default-map strings are split for non-unary parameters; refused for single-value repeatables."""
    if isinstance(value, str):
        if param.multiple and param.per_occurrence_arity == 1 and not param.is_variadic():
            raise BadParameter(
                f"{param.get_error_hint()} needs an iterable (sequence) default, not a string.",
                ctx,
                param,
            )
        if param._is_splitting() and not isinstance(param.type, Tuple):
            return tuple(param._convert_one(p, ctx) for p in param._split_env_value(value))
        if isinstance(param.type, Tuple):
            return param.convert_occurrence(value.split(), ctx)
        return param._convert_one(value, ctx)
    return value

