"""POSIX-style token parser for one command level (FP-01, FP-03, FP-04, FP-10)."""

from .exceptions import BadOptionUsage, BadArgumentUsage, NoSuchOption, UsageError
from .params import Argument, Option

_PREFIXES = ("-", "/", "+")


class ParseResult:
    def __init__(self):
        self.occurrences = {}  # id(param) -> list of raw occurrences
        self.counts = {}  # id(param) -> int, for counting options
        self.present = set()  # id(param) of parameters given on the command line
        self.prompt_pending = set()  # id(param) of prompting options given without a value
        self.values = {}  # id(param) -> converted-ready value (arguments and flags)
        self.rest = []  # tokens that belong to a subcommand (groups only)
        self.extra = []  # leftover tokens tolerated by allow_extra_args


class Parser:
    def __init__(self, ctx, command, interspersed=True):
        self.ctx = ctx
        self.command = command
        self.interspersed = interspersed
        self.result = ParseResult()
        self.lookup = {}
        self.help_names = set()
        self.options = [p for p in command.get_params() if isinstance(p, Option)]
        self.arguments = [p for p in command.get_params() if isinstance(p, Argument)]
        for p in self.options:
            for name in p.all_names():
                self.lookup[self._norm(name)] = (p, name in p.secondary_opts)
        if command.help_option_enabled(ctx):
