    if ctx.terminal_width:
        return int(ctx.terminal_width)
    auto = shutil.get_terminal_size((80, 20)).columns
    return min(auto, ctx.max_content_width)


def _claimed_help_names(cmd, ctx):
    claimed = set()
    for p in cmd.get_params():
        if isinstance(p, Option):
