import os
import re
import sys

from .core import Context, Group
from .params import Argument, Option

SHELLS = ("bash", "zsh", "fish", "powershell")


class CompletionItem:
    """A suggestion with optional help text. ``type`` is ``plain`` for ordinary values."""

    def __init__(self, value, help=None, type="plain"):
        self.value = value
        self.help = help
        self.type = type


