    return "_" + re.sub(r"[^A-Za-z0-9]", "_", os.path.basename(prog_name)).upper() + "_COMPLETE"


def maybe_complete(cli, prog_name, complete_var, args):
    """Return an exit status when completion mode ran, otherwise None."""
    var = complete_var or _var_name(prog_name)
    instruction = os.environ.get(var)
    if instruction is None:
        return None
    shell, _, action = instruction.partition("_")
    if shell not in SHELLS or action not in ("source", "complete"):
        return 1
    if action == "source":
        sys.stdout.write(registration_script(shell, prog_name, var))
        sys.stdout.flush()
        return 0
    words, incomplete = _completion_words(shell)
    for line in suggestions(cli, prog_name, words, incomplete, shell):
        sys.stdout.write(line + "\n")
    sys.stdout.flush()
    return 0


def _completion_words(shell):
    raw = os.environ.get("COMP_WORDS", "")
    tokens = raw.split(" ")
    cword = os.environ.get("COMP_CWORD", "")
    if shell == "fish":
        incomplete = cword
        words = tokens[1:]
        if words and words[-1] == incomplete:
            words = words[:-1]
        return words, incomplete
    try:
        index = int(cword)
    except ValueError:
        index = len(tokens)
    incomplete = tokens[index] if index < len(tokens) else ""
    return tokens[1:index], incomplete


def _visible_options(cmd, ctx):
    out = []
    for p in cmd.get_params():
        if isinstance(p, Option) and not p.hidden:
            out.append((p, p.all_names()))
    return out


def _option_suggestions(cmd, ctx, incomplete):
    names = []
    for p, opts in _visible_options(cmd, ctx):
        for name in opts:
            if name.startswith(incomplete):
                names.append(CompletionItem(name, help=p.help))
    if cmd.help_option_enabled(ctx):
        for name in ctx.help_option_names:
            if name.startswith(incomplete):
                names.append(CompletionItem(name, help="Show this message and exit."))
    return names


def _command_suggestions(cmd, ctx, incomplete):
    out = []
    for name in cmd.list_commands(ctx):
        sub = cmd.get_command(ctx, name)
        if sub is None or sub.hidden or not name.startswith(incomplete):
            continue
        out.append(CompletionItem(name, help=sub.short_help or (sub.help or "").split("\n")[0]))
    return out


