"""In-process runner for tests (FP-14, Interface Contract section 9)."""

import contextlib
import io
import os
import sys
import tempfile

from .exceptions import OptlynError


class _BytesSink:
    def __init__(self):
        self.chunks = []

    def write(self, data):
        self.chunks.append(bytes(data))
        return len(data)

    def flush(self):
        pass

    def getvalue(self):
        return b"".join(self.chunks)


class _CaptureStream:
    """A text stream that records writes separately and in a combined buffer."""

    def __init__(self, name, combined, charset, echo_to=None):
        self.name = name
        self.encoding = charset
        self.errors = "strict"
        self._combined = combined
        self._bytes = _BytesSink()
        self.buffer = _BytesWriter(self)
        self._text = []
        self._echo_to = echo_to

    def write(self, text):
        if isinstance(text, bytes):
            return self.buffer.write(text)
        self._text.append(text)
        self._combined.append((self.name, text))
        self._bytes.write(text.encode(self.encoding, "replace"))
        return len(text)

    def _write_bytes(self, data):
        self._bytes.write(data)
        text = data.decode(self.encoding, "replace")
        self._text.append(text)
        self._combined.append((self.name, text))
        return len(data)

    def flush(self):
        pass

    def isatty(self):
        return False

    def fileno(self):
        raise io.UnsupportedOperation("fileno")

    def getvalue(self):
        return "".join(self._text)

    def bytes_value(self):
        return self._bytes.getvalue()


class _BytesWriter:
    def __init__(self, owner):
        self._owner = owner

    def write(self, data):
        return self._owner._write_bytes(bytes(data))

    def flush(self):
        pass


class _InputStream(io.StringIO):
    """Standard input that can echo the lines actually read (FP-14)."""

    def __init__(self, data, echo_to=None):
        super().__init__(data)
        self._echo_to = echo_to

    def readline(self, *args):
        line = super().readline(*args)
        if self._echo_to is not None and line:
            self._echo_to.write(line)
        return line


class Result:
    def __init__(self, runner, stdout_stream, stderr_stream, combined, exit_code, exception, exc_info=None):
        self.runner = runner
        self.exit_code = exit_code
        self.exception = exception
        self.exc_info = exc_info
        self.stdout = stdout_stream.getvalue()
        self.stderr = stderr_stream.getvalue()
        self.stdout_bytes = stdout_stream.bytes_value()
        self.stderr_bytes = stderr_stream.bytes_value()
