        if catch_exceptions is None:
            catch_exceptions = self.catch_exceptions
        if isinstance(args, str):
            args = args.split()
        args = list(args or [])
        extra.setdefault("color", color)
        prog_name = extra.pop("prog_name", None) or cli.name or "cli"
        standalone = extra.pop("standalone_mode", True)
        with self.isolation(input=input, env=env, color=color) as (stdout, stderr, combined):
