        prog_name = extra.pop("prog_name", None) or cli.name or "cli"
        standalone = extra.pop("standalone_mode", True)
        with self.isolation(input=input, env=env, color=color) as (stdout, stderr, combined):
            exit_code = 0
            exception = None
            exc_info = None
            try:
                cli.main(args=args, prog_name=prog_name, standalone_mode=standalone, **extra)
            except SystemExit as exc:
                code = exc.code
                if code is None:
                    exit_code = 0
                elif isinstance(code, int):
                    exit_code = code
                else:
                    print(code, file=sys.stderr)
                    exit_code = 1
            except OptlynError as exc:
                exit_code = exc.exit_code
                exception = exc
                exc_info = sys.exc_info()
            except Exception as exc:
                if not catch_exceptions:
                    raise
                exception = exc
                exit_code = 1
                exc_info = sys.exc_info()
            return Result(self, stdout, stderr, combined, exit_code, exception, exc_info)

    @contextlib.contextmanager
    def isolated_filesystem(self, temp_dir=None):
        """Chdir into a fresh directory. The directory is left in place on exit (CF-153 choice)."""
        cwd = os.getcwd()
        path = tempfile.mkdtemp(dir=temp_dir)
        os.chdir(path)
        try:
            yield path
        finally:
            os.chdir(cwd)

