        return len(tok) > 1 and tok[0] in self.prefixes

    def _fire_eager(self, param):
        # Eager callbacks run as soon as the flag is typed, so the first one typed wins (FP-02).
        if param.is_eager and param.callback is not None:
            self.result.eager_fired.add(id(param))
            param.callback(self.ctx, param, True)

